 "content": "from collections import Counter, deque

def _components(grid, bg):
    h, w = len(grid), len(grid[0]); seen = set(); out = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)]); seen.add((r, c)); pts = set()
            while q:
                y, x = q.popleft(); pts.add((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            out.append((color, pts))
    return out

def _l(pts):
    r0=min(r for r,c in pts); r1=max(r for r,c in pts)
    c0=min(c for r,c in pts); c1=max(c for r,c in pts)
    if len(pts) < 5: return None
    for r in (r0,r1):
        for c in (c0,c1):
            if pts == ({(r,x) for x in range(c0,c1+1)} | {(y,c) for y in range(r0,r1+1)}):
                return r,c,(1 if r==r0 else -1),(1 if c==c0 else -1)
    return None

def transform(grid):
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    comps = _components(grid, bg)
    markers = [(len(p), col, p, _l(p)) for col,p in comps if _l(p)]
    if not markers: return [row[:] for row in grid]
    _, mc, mp, (r,c,vd,hd) = max(markers, key=lambda z:z[0])
    candidates=[]
    for color, pts in comps:
        if color == mc or _l(pts): continue
        r0=min(y for y,x in pts); r1=max(y for y,x in pts)
        c0=min(x for y,x in pts); c1=max(x for y,x in pts)
        # The marked corner points toward the nearest vertically elongated object.
        if r1-r0 <= c1-c0: continue
        cy=sum(y for y,x in pts)/len(pts)
        if (cy-r)*(-vd) <= 0: continue
        dy=max(r0-r,0,r-r1); dx=max(c0-c,0,c-c1)
        candidates.append((dy+dx,-len(pts),pts))
    if not candidates: return [row[:] for row in grid]
    target=min(candidates,key=lambda z:(z[0],z[1]))[2]
    out=[row[:] for row in grid]
    for y,x in target: out[y][x]=mc
    return out
